const msg = $input.first().json;
const headers = msg.headers || {};
const getH = (k) => String(headers[k] || headers[k.toLowerCase()] || '');
const from = String(msg.from?.value?.[0]?.address || msg.From || msg.from || '').toLowerCase();
const subject = String(msg.subject || msg.Subject || '');
const text = String(msg.text || msg.textPlain || msg.snippet || '');
let skip = false;
if (!from) skip = true;
if (getH('auto-submitted') && getH('auto-submitted') !== 'no') skip = true;
if (/^(auto:|automatic reply|out of office)/i.test(subject)) skip = true;
if (getH('list-unsubscribe')) skip = true;
if (/noreply|no-reply|donotreply|mailer-daemon/.test(from)) skip = true;
return [{ json: { shouldProcess: !skip, from, subject, text: text.slice(0, 4000), messageId: msg.id || '' } }];

let intent = 'other';
try {
  const j = JSON.parse($input.first().json.choices?.[0]?.message?.content);
  if (['order_status','product_question','refund_or_complaint','other'].includes(j.intent)) intent = j.intent;
} catch (e) {}
// Map intent -> your Gmail label ID (create labels in Gmail first, then paste IDs
// or simply select them after import). Placeholder IDs below:
const labelMap = {
  order_status: 'REPLACE_LABEL_ORDER',
  product_question: 'REPLACE_LABEL_PRODUCT',
  refund_or_complaint: 'REPLACE_LABEL_REFUND',
  other: 'REPLACE_LABEL_OTHER'
};
return [{ json: { intent, labelId: labelMap[intent], messageId: $('Filter Noise Emails').first().json.messageId } }];
